import {mountArtGame} from './art.mjs';
import {afterNarration} from './narration.mjs';
import {attachDragInteraction,sparkle,makeGameSounds} from './interactions.mjs';
const recipes={preschool:[{total:2,formula:'2 apples'},{total:3,formula:'3 apples'},{total:4,formula:'4 apples'}],kindergarten:[{total:3,formula:'1 + 2'},{total:5,formula:'2 + 3'},{total:6,formula:'4 + 2'}]};
const words={"preschool": [{"word": "APPLE", "icon": "🍎", "tokens": ["A"], "tail": "PPLE", "choices": ["S", "A", "B"]}, {"word": "BALL", "icon": "⚽", "tokens": ["B"], "tail": "ALL", "choices": ["A", "S", "B"]}, {"word": "SUN", "icon": "☀️", "tokens": ["S"], "tail": "UN", "choices": ["S", "B", "A"]}], "kindergarten": [{"word": "CAT", "icon": "🐱", "tokens": ["C", "AT"], "choices": ["AT", "C", "OG"]}, {"word": "DOG", "icon": "🐶", "tokens": ["D", "OG"], "choices": ["OG", "UN", "D"]}, {"word": "SUN", "icon": "☀️", "tokens": ["S", "UN"], "choices": ["UN", "AT", "S"]}]};
const shapeList=[{id:'circle',name:'circle',glyph:'●',color:'#df916d'},{id:'square',name:'square',glyph:'■',color:'#6d9c96'},{id:'triangle',name:'triangle',glyph:'▲',color:'#d8b95a'}];
export function newMiniGame(type,level){return {type,level,round:0,step:0,count:0,selected:null,matched:[],mistakes:0,done:false,outcome:'changed'}}
export function miniRound(s){if(s.type==='fruit')return recipes[s.level][Math.min(2,s.round)];if(s.type==='word')return words[s.level][Math.min(2,s.round)];if(s.type==='clock')return {hour:[3,6,9][Math.min(2,s.round)]};return {}}
export function miniMove(old,action){if(old.done)return old;const s={...old,matched:[...old.matched],outcome:'changed'};const wrong=()=>{s.mistakes++;s.outcome='wrong';return s};const next=()=>{s.round++;s.done=s.round===3;if(!s.done){s.step=0;s.count=0}s.outcome=s.done?'complete':'correct';return s};
 if(action.type==='drop'){
  if(s.type==='fruit'){if(action.value!=='apple'||action.target!=='blender')return s;action={type:'add'}}
  else if(s.type==='word'){if(action.target!==String(s.step))return s;action={type:'pick',value:action.value}}
  else if(s.type==='match'){if(!shapeList.some(x=>x.id===action.value)||!shapeList.some(x=>x.id===action.target)||s.matched.includes(action.value)||s.matched.includes(action.target))return s;if(action.value!==action.target)return wrong();s.selected=action.value;action={type:'place',value:action.target}}
  else return s;
 }
 if(s.type==='fruit'){if(action.type==='add')s.count=Math.min(10,s.count+1);if(action.type==='remove')s.count=Math.max(0,s.count-1);if(action.type==='check')return s.count===miniRound(s).total?next():wrong();return s}
 if(s.type==='balloon'&&action.type==='pick'){if(action.value!==s.step+1)return wrong();s.step++;s.done=s.step===(s.level==='preschool'?5:10);s.outcome=s.done?'complete':'correct';return s}
 if(s.type==='word'&&action.type==='pick'){if(action.value!==miniRound(s).tokens[s.step])return wrong();s.step++;s.outcome='correct';return s.step===miniRound(s).tokens.length?next():s}
 if(s.type==='clock'&&action.type==='pick')return action.value===miniRound(s).hour?next():wrong();
 if(s.type==='match'){if(action.type==='select'&&shapeList.some(x=>x.id===action.value)&&!s.matched.includes(action.value))s.selected=action.value;if(action.type==='place'&&s.selected&&!s.matched.includes(action.value)){if(s.selected!==action.value)return wrong();s.matched.push(action.value);s.selected=null;s.done=s.matched.length===3;s.outcome=s.done?'complete':'correct'}return s}return s;
}
function clockImage(hour){return `<svg class="garden-clock" viewBox="0 0 260 260" role="img" aria-label="Analog clock: long hand pointing to twelve, short hand pointing to ${hour}"><circle cx="130" cy="130" r="116" fill="#faedc1" stroke="#be8758" stroke-width="12"/><circle cx="130" cy="130" r="99" fill="#fffcf1"/>${Array.from({length:12},(_,i)=>{const n=i+1,t=n*Math.PI/6;return `<text x="${130+82*Math.sin(t)}" y="${136-82*Math.cos(t)}" text-anchor="middle" fill="#54634b" font-size="19" font-family="Nunito, sans-serif" font-weight="800">${n}</text>`}).join('')}<path d="M130 130V61" stroke="#789d98" stroke-width="9" stroke-linecap="round"/><path d="M130 130V85" transform="rotate(${hour*30} 130 130)" stroke="#d58762" stroke-width="12" stroke-linecap="round"/><circle cx="130" cy="130" r="9" fill="#466950"/></svg>`}
export function mountMiniGame({activity:a,container,onSuccess,onMistake,speak,soundEnabled=()=>true,artSession=null}){if(a.isArt)return mountArtGame({activity:a,container,onSuccess,onMistake,speak,soundEnabled,artSession});let s=newMiniGame(a.game,a.level),disposed=false,transitioning=false,cancelTransition=()=>{};const q=sel=>container.querySelector(sel);const all=sel=>[...container.querySelectorAll(sel)];let hintUsed=false;const sounds=makeGameSounds(soundEnabled);let cleanupDrag=()=>{};
 const tell=(text)=>{const el=q('.game-message');if(el)el.textContent=text};
 const names={fruit:'Recipe',word:'Word',clock:'Clock'};
 function intro(){if(s.type==='fruit')return `Put ${miniRound(s).formula}${s.level==='kindergarten'?' apples':''} in the blender. Drag an apple to the blender, or tap an apple to add one.`;if(s.type==='balloon')return s.done?'You found every balloon. Well done!':`Pop the balloons in order, starting with number ${s.step+1}.`;if(s.type==='word'){const r=miniRound(s);return s.level==='preschool'?`Complete the word ${r.word.toLowerCase()}. Choose its first letter.`:`Build the word ${r.word.toLowerCase()}. Drag the sound tiles into the boxes from left to right, or tap each tile.`}if(s.type==='match')return 'Let’s drag each shape to its home. You can also tap a shape, then tap its matching home.';return 'Look at the short hand. What time is it?'}
 function renderMini(){const r=miniRound(s);let body='';
 if(s.type==='fruit')body=`<div class="recipe-note"><span>PIKO’S RECIPE</span><strong>${r.formula}</strong><small>${s.level==='kindergarten'?'Add both numbers together':'Let’s count one by one'}</small></div><div class="fruit-station"><button class="fruit-source" data-action="add" data-drag="apple" data-drag-label="🍎" aria-label="Add one apple"><span>🍎</span><small>Drag or tap</small></button><div class="blender"><div class="blender-rim"></div><div class="blender-cup" data-drop="blender" aria-label="${s.count} apples in the blender">${Array.from({length:s.count},()=>'<span>🍎</span>').join('')}${s.count===0?'<span class="empty-cup">↓</span>':''}</div><div class="blender-base"><span>${s.count}</span><i>●</i></div></div><span class="station-friend" aria-hidden="true">🐰</span></div><div class="game-controls"><button class="chip" data-action="remove" ${s.count===0?'disabled':''}>− Take one out</button><button class="button" data-action="check">Make juice! ✨</button></div>`;
 if(s.type==='balloon'){const max=s.level==='preschool'?5:10;const order=max===5?[3,1,5,2,4]:[6,2,9,4,1,8,3,10,5,7];body=`<div class="balloon-goal">Find number <strong>${Math.min(max,s.step+1)}</strong><span>${s.step} of ${max} balloons</span></div><div class="balloon-field">${order.map((n,i)=>`<button class="number-balloon ${n<=s.step?'popped':''}" style="--balloon:${['#de967c','#91bcb1','#c0a4c7','#e3c574','#93b5d0'][i%5]};--tilt:${i%2?7:-7}deg" data-pick="${n}" aria-label="Balloon ${n}" ${n<=s.step?'disabled':''}>${n<=s.step?'✦':n}<i></i></button>`).join('')}</div><div class="field-ground">🌼 &nbsp; &nbsp; 🌱 &nbsp; &nbsp; 🐰 &nbsp; &nbsp; 🌿</div>`}
 if(s.type==='word')body=`<div class="word-picture" aria-label="Picture of ${r.word.toLowerCase()}">${r.icon}</div><div class="word-slots">${r.tokens.map((t,i)=>`<div data-drop="${i}" class="letter-slot ${i===s.step?'awaiting':''}">${i<s.step?t:'?'}</div>`).join('')}${r.tail?`<span class="word-tail">${r.tail}</span>`:''}</div><div class="letter-tray">${r.choices.map(t=>`<button class="letter-tile" data-token="${t}" data-drag="${t}" data-drag-label="${t}" ${r.tokens.slice(0,s.step).includes(t)?'disabled':''}>${t}</button>`).join('')}</div><p class="game-caption">${s.level==='preschool'?'Which letter is missing?':'Tap the sound tiles in order.'}</p>`;
 if(s.type==='match')body=`<div class="shape-destinations">${shapeList.map(x=>`<button class="shape-hole ${s.matched.includes(x.id)?'filled':''}" data-place="${x.id}" data-drop="${x.id}" aria-label="Home for ${x.name}" ${s.matched.includes(x.id)?'disabled':''}><span style="color:${s.matched.includes(x.id)?x.color:'#c6cbbb'}">${x.glyph}</span><small>${s.matched.includes(x.id)?'✓ A match!':x.name}</small></button>`).join('')}</div><div class="shape-tray">${[shapeList[2],shapeList[0],shapeList[1]].map(x=>`<button class="shape-piece ${s.selected===x.id?'selected':''}" data-shape="${x.id}" data-drag="${x.id}" data-drag-label="${x.glyph}" aria-label="Choose ${x.name}" aria-pressed="${s.selected===x.id}" ${s.matched.includes(x.id)?'disabled':''} style="color:${x.color}">${s.matched.includes(x.id)?'✓':x.glyph}</button>`).join('')}</div><p class="game-caption">${s.selected?'Now tap the home with the same shape.':'Choose a shape, then match it to its home.'}</p>`;
 if(s.type==='clock')body=`<div class="clock-stage">${clockImage(r.hour)}<span class="clock-friend" aria-hidden="true">🐻</span></div><div class="clock-key"><span>🟠 Short hand: hours</span><span>🟢 Long hand: minutes</span></div><div class="clock-options">${[r.hour, r.hour%12+1,(r.hour+10)%12+1].sort((x,y)=>x-y).map(n=>`<button class="option" data-pick="${n}">${n} o’clock</button>`).join('')}</div>`;
 container.innerHTML=`<div class="mini-game game-${s.type}"><div class="mini-instructions"><span class="piko-guide" aria-hidden="true">🐰</span><p>${intro()}</p><span class="round-label">${names[s.type]?`${names[s.type]} ${Math.min(3,s.round+1)}/3`:s.type==='match'?`${s.matched.length}/3 matches`:'Play at your own pace'}</span></div><div class="mini-scene">${body}</div><div class="game-message" role="status" aria-live="polite">${s.outcome==='wrong'?'Not quite yet. Let’s try again.':''}</div><div class="mini-help"><button class="chip" data-mini-help>☀ Piko’s hint</button></div></div>`;
 all('[data-action]').forEach(b=>b.onclick=()=>act({type:b.dataset.action}));all('[data-pick]').forEach(b=>b.onclick=()=>act({type:'pick',value:Number(b.dataset.pick)}));all('[data-token]').forEach(b=>b.onclick=()=>act({type:'pick',value:b.dataset.token}));all('[data-shape]').forEach(b=>b.onclick=()=>act({type:'select',value:b.dataset.shape}));all('[data-place]').forEach(b=>b.onclick=()=>act({type:'place',value:b.dataset.place}));q('[data-mini-help]').onclick=()=>{if(!hintUsed){hintUsed=true;onMistake()}const msg=s.type==='fruit'?`Count to ${r.total}. This recipe needs ${r.total} apples.`:s.type==='word'?`Word ${r.word.toLowerCase()}. Choose ${r.tokens[s.step]}.`:s.type==='balloon'?`Now tap balloon number ${s.step+1}.`:s.type==='clock'?`The short hand points to ${r.hour}. Choose ${r.hour} o’clock.`:'Choose a colored shape, then find its matching home.';tell(msg);speak(msg)};
 }
 function act(action){
  if(disposed||transitioning||s.done)return;
  const old=s, prevRound=s.round;s=miniMove(s,action);
  if(s.outcome==='wrong'){onMistake();renderMini();const msg=s.type==='fruit'?'Not quite the right number of apples. That’s okay. Let’s count together.':'Not a match yet. That’s okay. Piko will help you try again.';tell(msg);speak(msg);q('.mini-scene')?.classList.add('gentle-wiggle');return;}
  if(s.done){transitioning=true;renderMini();all('button').forEach(b=>b.disabled=true);sounds.play('good');sparkle(container);tell('Hooray! You finished everything. Thank you for exploring!');cancelTransition=afterNarration(speak,'Great exploring! You gave it a try!',650,()=>{if(!disposed)onSuccess()});return;}
  if(s.round!==prevRound){if(s.type==='word'){const slot=q('.letter-slot.awaiting');if(slot){slot.textContent=action.value;slot.classList.remove('awaiting')}}transitioning=true;container.dataset.locked='yes';all('button').forEach(b=>b.disabled=true);q('.mini-scene')?.classList.add(s.type==='fruit'?'juicing':'round-celebration');sounds.play('good');sparkle(container);const text=s.type==='word'?miniRound(old).word.toLowerCase()+'. Well done!':s.type==='clock'?'It is '+miniRound(old).hour+' o’clock. Well done!':'Just right! The juice is ready.';tell(text);cancelTransition=afterNarration(speak,text,2000,()=>{if(disposed)return;transitioning=false;delete container.dataset.locked;renderMini();q('button')?.focus();speak(intro())});return;}
  renderMini();
  if(s.type==='fruit'&&s.count!==old.count){sounds.play('drop');if(action.type==='drop')sparkle(container);q('.blender-cup')?.classList.add('fruit-land');speak(s.count===0?'The blender is empty. Let’s add some apples.':s.count+(s.count===1?' apple. ':' apples. ')+(s.count===miniRound(s).total?'Just right! Now tap Make juice.':'Keep going.'));}
  if(s.outcome==='correct'){sounds.play(s.type==='balloon'?'pop':'good');sparkle(container);const text=s.type==='balloon'?'Number '+s.step+'. Well done! Now find number '+(s.step+1)+'.':s.type==='word'?'Well done, '+action.value.toLowerCase()+'. Now choose '+miniRound(s).tokens[s.step].toLowerCase()+'.':'A match! The shape found its home. Let’s match another one.';tell(text);speak(text);}
  if(s.type==='match'&&s.selected){const shape=shapeList.find(x=>x.id===s.selected);speak('This is a '+shape.name+'. Now choose the home with the same shape.');}
  const selector=action.type==='add'||action.type==='remove'?'[data-action="'+action.type+'"]':s.type==='balloon'?'[data-pick="'+(s.step+1)+'"]':s.type==='word'?'[data-token="'+miniRound(s).tokens[s.step]+'"]':s.type==='match'?(s.selected?'[data-place="'+s.selected+'"]':'[data-shape]:not(:disabled)'):'button';q(selector)?.focus();
 }
 renderMini();
 cleanupDrag=attachDragInteraction(container,act,()=>{tell('It has not reached its home yet. Try dragging again, or tap to choose.');speak('Try dragging again. You can also tap it.');});
 speak('Hi! I’m Piko. '+intro());
 const cleanup=()=>{disposed=true;cancelTransition();cleanupDrag();sounds.close()};
 cleanup.replay=()=>{if(!transitioning&&!disposed)return speak('Let’s try it together. '+intro(),true)};
 return cleanup;
}
